#!/usr/bin/env node
/**
 * ts-rs 产物后处理（P2/P4，AGENTS.md §8.4）：
 *
 * 1. **绑定收敛**：ts-rs 对第三方类型（serde_json::JsonValue 等）默认输出到
 *    `{crate}/bindings/` 源码树内——复制进 `src/api/generated/bindings/` 并改写
 *    generated 内的相对导入，产物自包含（P4）。
 * 2. **barrel 生成**：扫描 `generated/*.ts` 自动生成 `index.ts`（此前为手工维护
 *    且漏导出 7 个类型的假"AUTO-GENERATED"文件——本脚本使其名副其实）。
 * 3. **event-guard 生成**（2026-08-25 审查 F-guard）：从生成的
 *    `EventDto.ts` 解析全部 `type: "..."` 字面量，覆写 `src/api/event-guard.ts`
 *    的 KNOWN_EVENT_KINDS——单一事实源，消除手抄漂移（此前缺
 *    reasoning_delta/session_created/step_started/step_ended，含幽灵
 *    hook_run/file_undone/compress，导致校验失败的真实事件被静默丢弃）。
 *
 * 用法：`node scripts/gen-types-post.mjs`（在 `cargo test --features ts` 之后执行）。
 */
import { readdirSync, readFileSync, writeFileSync, mkdirSync, cpSync, existsSync } from "node:fs";
import { join, dirname, relative } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const genDir = join(root, "src", "api", "generated");
const cratesRoot = join(root, "..", "..", "crates");

// ── 1. 绑定收敛：收集 crates/*/bindings/**/*.ts → generated/bindings/ ──
const bindingsDest = join(genDir, "bindings");
mkdirSync(bindingsDest, { recursive: true });

const bindingSources = [];
for (const crate of readdirSync(cratesRoot)) {
  const bdir = join(cratesRoot, crate, "bindings");
  if (!existsSync(bdir)) continue;
  // 递归收集
  const walk = (dir) => {
    for (const e of readdirSync(dir, { withFileTypes: true })) {
      const full = join(dir, e.name);
      if (e.isDirectory()) walk(full);
      else if (e.name.endsWith(".ts")) bindingSources.push({ crate, full });
    }
  };
  walk(bdir);
}
for (const { crate, full } of bindingSources) {
  // 去掉 crate 段：不同 crate 对同一第三方类型的绑定内容一致，取单一规范副本
  const rel = relative(join(cratesRoot, crate, "bindings"), full);
  const dest = join(bindingsDest, rel);
  mkdirSync(dirname(dest), { recursive: true });
  cpSync(full, dest);
}

// ── 2. 改写 generated/*.ts 中指向源码树的绑定导入 ──
let rewritten = 0;
for (const f of readdirSync(genDir)) {
  if (!f.endsWith(".ts") || f === "index.ts") continue;
  const p = join(genDir, f);
  let src = readFileSync(p, "utf-8");
  const before = src;
  src = src.replaceAll(
    /(["'])((?:\.\.\/)+)minicoding-(?:core|protocol|server)?\/bindings\//g,
    "$1./bindings/",
  );
  if (src !== before) {
    writeFileSync(p, src);
    rewritten += 1;
  }
}

// ── 3. barrel：index.ts 由实际文件清单生成 ──
const files = readdirSync(genDir)
  .filter((f) => f.endsWith(".ts") && f !== "index.ts" && !f.endsWith(".test.ts"))
  .sort();
const lines = [
  "// This file is auto-generated by scripts/gen-types-post.mjs. Do not edit manually.",
  "// （P2：真正的自动 barrel——新增/删除生成文件后由 gen-types 流程重生成。）",
  "",
];
for (const f of files) {
  const name = f.replace(/\.ts$/, "");
  lines.push(`export type { ${name} } from "./${name}";`);
}
lines.push("");
writeFileSync(join(genDir, "index.ts"), lines.join("\n"));

// ── 4. event-guard：从 EventDto.ts 提取 kind 字面量，覆写 event-guard.ts ──
// 注：本步骤在 oxfmt 之前执行，输入是 ts-rs 原始输出（`"type": "token", ...`）；
// 正则同时兼容 oxfmt 风格（`{ type: "token"; ... }`）以便单独重跑。
const eventDtoSrc = readFileSync(join(genDir, "EventDto.ts"), "utf-8");
const kinds = [...eventDtoSrc.matchAll(/\{ ?"?type"? ?: "([a-z_]+)"/g)].map((m) => m[1]);
if (kinds.length === 0) {
  throw new Error("[gen-types-post] EventDto.ts 中未解析到任何 type 字面量，中止覆写");
}

const guardSrc = `/**
 * EventDto 运行时校验（Zod，AGENTS.md §8.4 完整落地——2026-08-23 遗留#4）。
 *
 * SSE 数据必须通过本 schema 才进入业务层，防止后端 schema 漂移导致
 * 运行时 undefined。KNOWN_EVENT_KINDS 由 scripts/gen-types-post.mjs 从
 * src/api/generated/EventDto.ts 的判别联合自动提取（单一事实源，
 * 2026-08-25 审查 F-guard：手抄清单漂移曾把 reasoning_delta/session_created/
 * step_started/step_ended 静默丢弃）。
 *
 * This file is auto-generated by scripts/gen-types-post.mjs. Do not edit manually.
 */
import { z } from "zod";

const KNOWN_EVENT_KINDS = z.enum([
${kinds.map((k) => `  "${k}",`).join("\n")}
]);

export const eventDtoSchema = z
  .object({
    type: KNOWN_EVENT_KINDS,
    // R8 FE-8：SSE data 载荷已含 seq（服务端 format_sse_event 注入），
    // 与生成类型 EventDto.seq 必填对齐。RehydrateRequired（无 type）在
    // isRehydratePayload 分支先行识别，不经本 schema。
    seq: z.number(),
  })
  .passthrough();

export type ParsedEventDto = z.infer<typeof eventDtoSchema> & Record<string, unknown>;

/** 校验并返回类型化事件；失败返回 \`null\`（调用方 warn 后丢弃）。 */
export function isEventDto(
  value: unknown,
): value is { type: string; seq: number } & Record<string, unknown> {
  return eventDtoSchema.safeParse(value).success;
}
`;
writeFileSync(join(root, "src", "api", "event-guard.ts"), guardSrc);

console.log(
  `[gen-types-post] bindings copied: ${bindingSources.length}, files rewritten: ${rewritten}, barrel entries: ${files.length}, event kinds: ${kinds.length}`,
);
